from collections import deque


def escapeMinutes(grid):
    rows, cols = len(grid), len(grid[0])
    INF = 10 ** 9
    fire = [[INF] * cols for _ in range(rows)]
    q = deque()
    start = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                fire[r][c] = 0
                q.append((r, c))
            elif grid[r][c] == 3:
                start = (r, c)
    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] != 1 and fire[ny][nx] == INF:
                fire[ny][nx] = fire[y][x] + 1
                q.append((ny, nx))

    def on_border(y, x):
        return y in (0, rows - 1) or x in (0, cols - 1)

    if on_border(*start):
        return 1
    dist = {start: 0}
    q = deque([start])
    while q:
        y, x = q.popleft()
        d = dist[(y, x)] + 1
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] != 1 and (ny, nx) not in dist and d < fire[ny][nx]:
                if on_border(ny, nx):
                    return d + 1
                dist[(ny, nx)] = d
                q.append((ny, nx))
    return -1
